import { useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';
import {
  ArrowDownToLine,
  Trash2,
  Play,
  SlidersHorizontal,
  Search,
  Plus,
  Pause,
  MonitorPlay,
} from 'lucide-react';
import type {
  AudioLang,
  MediaDetail,
  MediaType,
  Source,
  SourceFilters,
  SourceSortKey,
  TvEpisode,
} from '../types';
import {
  cardPosterUrl,
  createDownload,
  externalPlayerUrl,
  humanEta,
  humanSize,
  humanSpeed,
  mediaDetails,
  pauseDownload,
  removeDownload,
  resumeDownload,
  seasonEpisodes,
  sources,
} from '../api';
import { SourceRow } from '../components/SourceRow';
import { StateBadge } from '../components/StateBadge';
import { activeFilterCount, filterSources, groupSources, sortSources } from '../lib/release';
import { chooseEpisodePick, chooseSeasonPick } from '../lib/coverage';
import { episodeToken } from '../lib/episode';
import { useDownloadsStore } from '../store/downloadsStore';
import { useToastStore } from '../store/toastStore';
import { useRecentsStore } from '../store/recentsStore';
import { useAudioLanguage } from '../store/settingsStore';
import { useVersionStore, versionKey } from '../store/versionStore';
import {
  bestPlayable,
  leadCopy,
  playable,
  sortVersions,
  versionLabel,
} from '../lib/versions';
import { audioChipLabel, audioLanguageLabel } from '../lib/audio';
import type { DownloadRecord } from '../types';

const PAGE_SIZE = 30;
const RESOLUTIONS = ['2160p', '1080p', '720p', '480p'];
const CODECS = ['x264', 'x265', 'AV1', 'XviD', 'DivX'];

const emptyFilters: SourceFilters = {
  indexers: [],
  resolutions: [],
  sources: [],
  codecs: [],
  minSeeders: null,
  minSizeGB: null,
  maxSizeGB: null,
  regex: '',
};

function pickQuality(source: Source): string | null {
  const parts: string[] = [];
  if (source.resolution) parts.push(source.resolution);
  if (source.source) parts.push(source.source);
  if (source.codec) parts.push(source.codec);
  if (source.isDolbyVision) parts.push('DoVi');
  else if (source.hdr) parts.push('HDR');
  return parts.length > 0 ? parts.join(' · ') : null;
}

function pickSummary(source: Source): string {
  const bits: string[] = [];
  bits.push(humanSize(source.sizeBytes));
  if (source.indexer) bits.push(source.indexer);
  bits.push(`${source.seeders} seeds`);
  return bits.join(' · ');
}

/** Small caption under the primary Download button naming the friendly pick. */
function movieOfferHint(source: Source | null): string | null {
  if (!source) return null;
  const bits: string[] = [];
  const q = pickQuality(source);
  if (q) bits.push(q);
  bits.push(humanSize(source.sizeBytes));
  bits.push(`${source.seeders} seeds`);
  return bits.length > 0 ? `Best match · ${bits.join(' · ')}` : 'Best match available';
}

