  color: var(--white);
  text-transform: uppercase;
  line-height: 1.05;
}
.dh-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  color: var(--text-1);
  font-size: 14px;
  margin-bottom: 14px;
}
.dh-meta-chip {
  border: 1px solid var(--border-strong);
  color: var(--text-1);
  font-size: 11px;
  font-weight: 700;
  padding: 1px 7px;
  border-radius: 3px;
}
.dh-overview {
  max-width: 640px;
  margin: 0 0 22px;
  color: var(--text-1);
  font-size: 15px;
}
.dh-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  align-items: center;
}
.dh-extra {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.dh-active {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  color: var(--text-2);
}

/* Movie / season hero download states */
.dh-offer-main {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
}
.dh-offer-hint {
  font-size: 12px;
  color: var(--text-3);
  padding-left: 22px;
}
.dh-nosource {
  margin: 0;
  max-width: 480px;
  color: var(--text-2);
  font-size: 14px;
}
.version-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.version-chip {
  padding: 4px 12px;
  border-radius: 999px;
  border: 1px solid var(--border-strong);
  background: rgba(10, 10, 10, 0.72);
  color: var(--text-2);
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  transition: color 0.15s ease, border-color 0.15s ease, background-color 0.15s ease;
}
.version-chip:hover {
  color: var(--white);
  border-color: var(--white);
}
.version-chip.active {
  background: var(--white);
  border-color: transparent;
  color: var(--bg);
  font-weight: 700;
}

.hero-status {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: min(520px, 92vw);
  padding: 16px 18px;
  border-radius: 10px;
  background: rgba(10, 10, 10, 0.78);
  border: 1px solid var(--border-weak);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(6px);
}
.hero-status-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.hero-status-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--white);
}
.hero-status-bar {
  display: flex;
  align-items: center;
  gap: 14px;
}
.hero-status-pct {
  font-size: 30px;
  font-weight: 800;
  line-height: 1;
  color: var(--white);
  font-variant-numeric: tabular-nums;
  min-width: 72px;
  text-align: right;
}
.hero-progress {
  flex: 1;
  height: 6px;
  border-radius: 3px;
}
.hero-status-meta {
  display: flex;
  gap: 16px;
  font-size: 12.5px;
  color: var(--text-3);
  font-variant-numeric: tabular-nums;
}
.hero-status-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.hero-mini-dl {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 6px;
}
.hero-mini-row {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  color: var(--text-2);
}
.hero-mini-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 320px;
}
.hero-mini-pct {
  font-variant-numeric: tabular-nums;
  color: var(--text-3);
  min-width: 38px;
  text-align: right;
}

/* Detail body container */
.detail-body {
  padding: 0 var(--gutter) 50px;
}

