  const pop = document.querySelector('.tc-pop');
  if (!pop) return { open: false };
  const cs = (el, props) => {
    const s = getComputedStyle(el);
    const out = {};
    props.forEach((p) => { out[p] = s[p]; });
    return out;
  };
  const details = pop.querySelector('.tc-pop-details');
  const actions = pop.querySelector('.tc-pop-actions');
  const variants = pop.querySelector('.tc-pop-variants');
  const meta = pop.querySelector('.tc-pop-meta');
  const cert = pop.querySelector('.tc-pop-cert');
  const hd = pop.querySelector('.tc-pop-hd');
  const metaText = pop.querySelector('.tc-pop-meta-text');
  const tags = pop.querySelector('.tc-pop-tags');
  const sep = pop.querySelector('.tc-pop-tag-sep');
  const title = pop.querySelector('.tc-pop-title');
  const sound = pop.querySelector('.tc-pop-sound');
  const r = {};
  r.open = true;
  r.detailsPadding = cs(details, ['paddingTop', 'paddingRight', 'paddingBottom', 'paddingLeft']);
  r.actionsGap = cs(actions, ['gap']);
  r.variantsGap = variants ? cs(variants, ['gap', 'marginTop']) : null;
  r.meta = meta ? cs(meta, ['gap', 'marginTop', 'fontSize', 'color', 'lineHeight']) : null;
  r.metaTextColor = metaText ? cs(metaText, ['color', 'fontSize']) : null;
  r.cert = cert ? cs(cert, ['border', 'borderRadius', 'padding', 'fontSize', 'fontWeight', 'color', 'background']) : null;
  r.hd = hd ? cs(hd, ['border', 'borderRadius', 'padding', 'fontSize', 'fontWeight', 'color', 'background']) : null;
  r.tags = tags ? cs(tags, ['gap', 'marginTop', 'fontSize', 'color']) : null;
  r.sep = sep ? cs(sep, ['marginRight', 'color']) : null;
  r.mediaTitleInset = cs(title, ['left', 'bottom']);
  r.soundInset = sound ? cs(sound, ['right', 'bottom']) : null;
  r.popText = pop.textContent.replace(/\s+/g, ' ').trim();
  return r;
}

